head.script:
///////// 1. 변수 및 선언 영역 /////////
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 숨김처리
        txb_InitTpCd.hide();
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_1);
        // 파라미터설정
        await scwin.setParam();

        // 목록조회
        /*
        dts_List.SyncLoad = true;
        dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_INFO";
        dts_List.Reset();
        dts_List.SyncLoad = false;
         */

        // 초기기관정보설정
        if (txb_InitTpCd.getValue() !== '') {
            scwin.initInstInfo();
            return;
        }
        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_InstNm_onkeypress
 * @description txb_InstNm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_InstNm_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.txb_InstNm_onkeypress" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            if (dts_List.getCellData(row, "INST_STAT_CD") !== '1') {
                await $c.win.alert('기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
                return;
            }
            let arrPar = new Array();
            arrPar[0] = {
                INST_CD: dts_List.getCellData(row, "INST_CD"),
                INST_NM: dts_List.getCellData(row, "INST_NM")
            };
            fn_SetPar(arrPar);
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_init_onclick
 * @description 「초기화」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_init_onclick = function() {
    try {
        scwin.initInstInfo();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21102.btn_init_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21102.dts_List_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기관 데이터를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_INFO";
    url += "&queryId=lds.stf.bnscommon.select.listInstCd";
    url += "&SCREN_ID=" + 'ULDSTF05100.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_NM=" + txb_InstNm.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initInstInfo
 * @description 기관 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.initInstInfo = function() {
    dts_List.removeAll();
    grd_List.Redraw = false;
    const initTpCd = txb_InitTpCd.getValue();
    // 대표주관회사
    if (initTpCd === '1') {
        scwin.setRepMajagntCom();
    }
    // 보증기관
    else if (initTpCd === '2') {
        scwin.setGuarInst();
    }
    // 등록기관
    else if (initTpCd === '3') {
        scwin.setRegnst();
    }
    // 원리금지급대행기관
    else if (initTpCd === '4') {
        scwin.setPrincintPayAgnt();
    }
    // 수탁기관
    else if (initTpCd === '5') {
        scwin.setTrstInst();
    }
    grd_List.Redraw = true;
};

