/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        fn_GetPar = prt.fn_GetPar;
        fn_SetPar = prt.fn_SetPar;
    }
    if (fn_GetPar !== undefined) {
        let arrPar = new Array();
        fn_GetPar(arrPar);
        if (typeof(arrPar[0].LBL_NM !== 'undefined') &&
            arrPar[0].LBL_NM !== '') {
            txb_LblNm.setValue(arrPar[0].LBL_NM);
        }
        // 0:조회, 1:대표주관회사, 2:보증기관, 3:등록기관, 4:원리금지급대행기관, 5:수탁기관/사채관리회사
        if (typeof(arrPar[0].INIT_TP_CD !== 'undefined')) {
            txb_InitTpCd.setValue(arrPar[0].INIT_TP_CD);
        } else {
            txb_InitTpCd.setValue('0');
            txb_InstNm.setValue(arrPar[0].INST_CD);
            await scwin.search();
        }
    }
};
